arguments.content:
/* ===== RESET & BASE ===== */
*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: "SF Pro Display", "SF Pro Text", "Helvetica Neue", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  color: #1d1d1f;
  background: #fff;
  line-height: 1.47059;
  font-weight: 400;
  letter-spacing: -0.022em;
}

a {
  color: #0066cc;
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}

img {
  max-width: 100%;
  display: block;
}

button {
  cursor: pointer;
  border: none;
  background: none;
  font-family: inherit;
}

/* ===== NAVIGATION ===== */
.nav {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: rgba(255, 255, 255, 0.8);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid rgba(0, 0, 0, 0.08);
}

.nav-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 22px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 44px;
}

.nav-logo {
  font-size: 21px;
  font-weight: 600;
  color: #1d1d1f;
  letter-spacing: -0.02em;
}

.nav-logo:hover {
  text-decoration: none;
}

.nav-links {
  display: flex;
  gap: 28px;
}

.nav-links a {
  font-size: 13px;
  font-weight: 400;
  color: #1d1d1f;
  letter-spacing: -0.01em;
  transition: color 0.15s;
}

.nav-links a:hover {
  color: #0066cc;
  text-decoration: none;
}

.nav-actions {
  display: flex;
  gap: 18px;
  align-items: center;
}

.nav-actions i {
  font-size: 18px;
  color: #1d1d1f;
  cursor: pointer;
  transition: color 0.15s;
}

.nav-actions i:hover {
  color: #0066cc;
}

.nav-mobile-toggle {
  display: none;
  font-size: 22px;
  color: #1d1d1f;
}

/* ===== RIBBON BANNER ===== */
.ribbon {
  background: #f5f5f7;
  text-align: center;
  padding: 10px 22px;
  font-size: 13px;
  color: #1d1d1f;
  letter-spacing: -0.01em;
}

.ribbon a {
  color: #0066cc;
  font-weight: 400;
}

/* ===== HERO ===== */
.hero {
  text-align: center;
  padding: 80px 22px 60px;
  background: #f5f5f7;
}

.hero-label {
  font-size: 28px;
  font-weight: 600;
  color: #6e6e73;
  letter-spacing: -0.02em;
  margin-bottom: 8px;
}

.hero-title {
  font-size: 56px;
  font-weight: 700;
  letter-spacing: -0.025em;
  line-height: 1.07;
  margin-bottom: 12px;
}

.hero-subtitle {
  font-size: 21px;
  font-weight: 400;
  color: #6e6e73;
  letter-spacing: -0.02em;
  margin-bottom: 28px;
}

.hero-actions {
  display: flex;
  justify-content: center;
  gap: 20px;
  flex-wrap: wrap;
}

.btn-primary {
  display: inline-block;
  background: #0071e3;
  color: #fff;
  padding: 11px 21px;
  border-radius: 980px;
  font-size: 15px;
  font-weight: 500;
  letter-spacing: -0.01em;
  transition: background 0.2s;
}

.btn-primary:hover {
  background: #0077ed;
  text-decoration: none;
}

.btn-outline {
  display: inline-block;
  color: #0071e3;
  padding: 11px 21px;
  border-radius: 980px;
  font-size: 15px;
  font-weight: 500;
  letter-spacing: -0.01em;
  border: 1px solid #0071e3;
  transition: background 0.2s, color 0.2s;
}

.btn-outline:hover {
  background: #0071e3;
  color: #fff;
  text-decoration: none;
}

.btn-link {
  display: inline-block;
  color: #0066cc;
  font-size: 15px;
  font-weight: 500;
  letter-spacing: -0.01em;
  padding: 11px 0;
}

.btn-link:hover {
  text-decoration: underline;
}

.btn-link i {
  font-size: 14px;
  margin-left: 2px;
}

/* ===== SECTION ===== */
.section {
  padding: 80px 0;
}

.section-light {
  background: #f5f5f7;
}

.section-dark {
  background: #1d1d1f;
  color: #fff;
}

.section-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 22px;
}

.section-label {
  font-size: 14px;
  font-weight: 600;
  color: #6e6e73;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  margin-bottom: 8px;
}

.section-heading {
  font-size: 40px;
  font-weight: 700;
  letter-spacing: -0.025em;
  line-height: 1.1;
  margin-bottom: 10px;
}

.section-heading.light {
  color: #fff;
}

.section-subheading {
  font-size: 19px;
  font-weight: 400;
  color: #6e6e73;
  letter-spacing: -0.02em;
  margin-bottom: 36px;
}

.section-subheading.light {
  color: #a1a1a6;
}

.section-promo {
  font-size: 14px;
  color: #6e6e73;
  margin-bottom: 30px;
  letter-spacing: -0.01em;
}

/* ===== PRODUCT GRID (HOMEPAGE) ===== */
.product-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
  padding: 0 22px;
  max-width: 1200px;
  margin: 0 auto;
}

.product-tile {
  position: relative;
  border-radius: 18px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding: 60px 30px 40px;
  min-height: 500px;
  background: #f5f5f7;
}

.product-tile-image {
  width: 100%;
  height: 260px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
}

.product-tile-image .placeholder {
  border-radius: 12px;
}

.product-tile-headline {
  font-size: 32px;
  font-weight: 700;
  letter-spacing: -0.025em;
  line-height: 1.1;
  margin-bottom: 8px;
  color: #1d1d1f;
}

.product-tile-headline.light {
  color: #fff;
}

.product-tile-tagline {
  font-size: 18px;
  font-weight: 400;
  color: #6e6e73;
  letter-spacing: -0.02em;
  margin-bottom: 20px;
  max-width: 320px;
}

.product-tile-tagline.light {
  color: #a1a1a6;
}

.product-tile-actions {
  display: flex;
  gap: 24px;
}

/* Product tile gradient backgrounds */
.tile-phone {
  background: linear-gradient(135deg, #fce4ec 0%, #f8bbd0 40%, #f48fb1 100%);
}

.tile-laptop-neo {
  background: linear-gradient(135deg, #e3f2fd 0%, #bbdefb 40%, #90caf9 100%);
}

.tile-tablet-pro {
  background: linear-gradient(135deg, #e8f5e9 0%, #c8e6c9 40%, #a5d6a7 100%);
}

.tile-laptop-pro {
  background: linear-gradient(135deg, #ede7f6 0%, #d1c4e9 40%, #b39ddb 100%);
}

.tile-earbuds {
  background: linear-gradient(135deg, #f3e5f5 0%, #e1bee7 40%, #ce93d8 100%);
}

.tile-trade-in {
  background: linear-gradient(135deg, #fff3e0 0%, #ffe0b2 40%, #ffcc80 100%);
}

/* ===== CATEGORY HERO ===== */
.category-hero {
  background: #f5f5f7;
  text-align: center;
  padding: 60px 22px 40px;
}

.category-hero-title {
  font-size: 48px;
  font-weight: 700;
  letter-spacing: -0.025em;
  line-height: 1.1;
  margin-bottom: 10px;
}

.category-hero-subtitle {
  font-size: 19px;
  color: #6e6e73;
  letter-spacing: -0.02em;
}

/* ===== STICKY SECTION NAV ===== */
.section-nav {
  position: sticky;
  top: 44px;
  z-index: 999;
  background: rgba(255, 255, 255, 0.8);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid rgba(0, 0, 0, 0.08);
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.section-nav-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 22px;
  display: flex;
  gap: 0;
}

.section-nav-inner a {
  display: block;
  padding: 14px 18px;
  font-size: 13px;
  font-weight: 500;
  color: #6e6e73;
  white-space: nowrap;
  border-bottom: 2px solid transparent;
  transition: color 0.15s, border-color 0.15s;
  letter-spacing: -0.01em;
}

.section-nav-inner a:hover,
.section-nav-inner a.active {
  color: #1d1d1f;
  border-bottom-color: #1d1d1f;
  text-decoration: none;
}

/* ===== STORE HERO ===== */
.store-hero {
  background: #f5f5f7;
  text-align: center;
  padding: 60px 22px 48px;
}

.store-hero-title {
  font-size: 48px;
  font-weight: 700;
  letter-spacing: -0.025em;
  line-height: 1.1;
  margin-bottom: 10px;
}

.store-hero-subtitle {
  font-size: 21px;
  color: #6e6e73;
  letter-spacing: -0.02em;
  margin-bottom: 24px;
}

/* ===== PRODUCT ICON BAR ===== */
.product-icon-bar {
  background: #fff;
  border-bottom: 1px solid rgba(0, 0, 0, 0.06);
}

.product-icon-bar-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 16px 22px;
  display: flex;
  gap: 12px;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}

.product-icon-bar-inner::-webkit-scrollbar {
  display: none;
}

.product-icon-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  min-width: 80px;
  cursor: pointer;
  padding: 8px 4px;
  transition: opacity 0.15s;
}

.product-icon-item:hover {
  opacity: 0.7;
  text-decoration: none;
}

.product-icon-circle {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
  color: #fff;
  font-weight: 600;
}

.product-icon-label {
  font-size: 11px;
  font-weight: 500;
  color: #1d1d1f;
  letter-spacing: -0.01em;
  text-align: center;
}

/* ===== CAROUSEL ===== */
.carousel-section {
  padding: 60px 0;
}

.carousel-section-light {
  background: #f5f5f7;
}

.carousel-section-dark {
  background: #1d1d1f;
}

.carousel-header {
  max-width: 1200px;
  margin: 0 auto 30px;
  padding: 0 22px;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
}

.carousel-header-info {
  flex: 1;
}

.carousel-header-info .section-label {
  margin-bottom: 6px;
}

.carousel-header-info .section-heading {
  font-size: 32px;
  margin-bottom: 6px;
}

.carousel-header-info .section-subheading {
  font-size: 17px;
  margin-bottom: 0;
}

.carousel-arrows {
  display: flex;
  gap: 8px;
  flex-shrink: 0;
}

.carousel-arrow {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: rgba(0, 0, 0, 0.05);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  color: #1d1d1f;
  transition: background 0.2s, opacity 0.2s;
}

.carousel-arrow:hover {
  background: rgba(0, 0, 0, 0.1);
}

.carousel-arrow:disabled {
  opacity: 0.3;
  cursor: default;
}

.carousel-arrow.light {
  background: rgba(255, 255, 255, 0.15);
  color: #fff;
}

.carousel-arrow.light:hover {
  background: rgba(255, 255, 255, 0.25);
}

.carousel-track {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 22px;
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scroll-behavior: smooth;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}

.carousel-track::-webkit-scrollbar {
  display: none;
}

/* ===== CAROUSEL CARDS ===== */
.carousel-card {
  flex: 0 0 320px;
  scroll-snap-align: start;
  background: #fff;
  border-radius: 18px;
  overflow: hidden;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.06);
  transition: transform 0.2s, box-shadow 0.2s;
}

.carousel-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 28px rgba(0, 0, 0, 0.1);
}

.carousel-card-image {
  width: 100%;
  height: 220px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #fafafa;
}

.carousel-card-body {
  padding: 20px 24px 24px;
}

.carousel-card-badge {
  display: inline-block;
  font-size: 11px;
  font-weight: 600;
  color: #bf4800;
  letter-spacing: 0.02em;
  margin-bottom: 6px;
}

.carousel-card-name {
  font-size: 18px;
  font-weight: 600;
  letter-spacing: -0.02em;
  margin-bottom: 4px;
}

.carousel-card-tagline {
  font-size: 14px;
  color: #6e6e73;
  letter-spacing: -0.01em;
  margin-bottom: 14px;
}

.carousel-card-price {
  font-size: 15px;
  font-weight: 500;
  letter-spacing: -0.01em;
  color: #1d1d1f;
  margin-bottom: 4px;
}

.carousel-card-monthly {
  font-size: 13px;
  color: #6e6e73;
  letter-spacing: -0.01em;
}

.carousel-card-note {
  font-size: 12px;
  color: #6e6e73;
  letter-spacing: -0.01em;
}

/* Dark variant cards */
.carousel-card.dark {
  background: #2d2d2f;
  color: #f5f5f7;
}

.carousel-card.dark .carousel-card-name,
.carousel-card.dark .carousel-card-price {
  color: #f5f5f7;
}

.carousel-card.dark .carousel-card-tagline,
.carousel-card.dark .carousel-card-monthly,
.carousel-card.dark .carousel-card-note {
  color: #a1a1a6;
}

/* Help & support cards */
.help-card {
  flex: 0 0 280px;
  scroll-snap-align: start;
  background: #fff;
  border-radius: 18px;
  padding: 32px 24px;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.06);
  text-align: center;
}

.help-card-icon {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: #f5f5f7;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 28px;
  color: #0071e3;
  margin: 0 auto 16px;
}

.help-card-title {
  font-size: 17px;
  font-weight: 600;
  letter-spacing: -0.02em;
  margin-bottom: 8px;
}

.help-card-desc {
  font-size: 14px;
  color: #6e6e73;
  letter-spacing: -0.01em;
}

/* Store difference cards */
.diff-card {
  flex: 0 0 240px;
  scroll-snap-align: start;
  text-align: center;
}

.diff-card-icon {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: #f5f5f7;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 28px;
  color: #0071e3;
  margin: 0 auto 14px;
}

.diff-card-title {
  font-size: 15px;
  font-weight: 600;
  letter-spacing: -0.02em;
  margin-bottom: 6px;
}

.diff-card-desc {
  font-size: 13px;
  color: #6e6e73;
  letter-spacing: -0.01em;
}

/* Store savings cards */
.savings-card {
  flex: 0 0 260px;
  scroll-snap-align: start;
  background: #fff;
  border-radius: 18px;
  padding: 28px 22px;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.06);
}

.savings-card-icon {
  font-size: 32px;
  color: #0071e3;
  margin-bottom: 14px;
}

.savings-card-title {
  font-size: 17px;
  font-weight: 600;
  letter-spacing: -0.02em;
  margin-bottom: 8px;
}

.savings-card-desc {
  font-size: 14px;
  color: #6e6e73;
  letter-spacing: -0.01em;
}

/* Guide cards */
.guide-card {
  flex: 0 0 260px;
  scroll-snap-align: start;
  background: #fff;
  border-radius: 18px;
  overflow: hidden;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.06);
}

.guide-card-image {
  width: 100%;
  height: 140px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #fafafa;
  font-size: 40px;
}

.guide-card-body {
  padding: 18px 22px 22px;
}

.guide-card-title {
  font-size: 17px;
  font-weight: 600;
  letter-spacing: -0.02em;
  margin-bottom: 4px;
}

.guide-card-desc {
  font-size: 14px;
  color: #6e6e73;
  letter-spacing: -0.01em;
}

/* Brand collab card */
.brand-collab-card {
  flex: 0 0 400px;
  scroll-snap-align: start;
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
  border-radius: 18px;
  padding: 40px 32px;
  color: #fff;
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-height: 280px;
}

.brand-collab-card .collab-badge {
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: #f5a623;
  margin-bottom: 8px;
}

.brand-collab-card .collab-title {
  font-size: 28px;
  font-weight: 700;
  letter-spacing: -0.025em;
  line-height: 1.1;
  margin-bottom: 10px;
}

.brand-collab-card .collab-desc {
  font-size: 16px;
  color: #a1a1a6;
  letter-spacing: -0.02em;
  margin-bottom: 20px;
}

/* ===== ENTERTAINMENT TABS ===== */
.entertainment {
  padding: 80px 0;
  background: #f5f5f7;
}

.entertainment-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 22px;
}

.ent-tabs {
  display: flex;
  gap: 28px;
  margin-bottom: 32px;
  border-bottom: 1px solid rgba(0, 0, 0, 0.08);
  padding-bottom: 14px;
}

.ent-tab {
  font-size: 17px;
  font-weight: 500;
  color: #6e6e73;
  padding-bottom: 14px;
  margin-bottom: -15px;
  border-bottom: 2px solid transparent;
  transition: color 0.15s, border-color 0.15s;
  letter-spacing: -0.01em;
}

.ent-tab:hover {
  color: #1d1d1f;
}

.ent-tab.active {
  color: #1d1d1f;
  border-bottom-color: #1d1d1f;
}

.ent-content {
  display: none;
}

.ent-content.active {
  display: block;
}

.ent-content-track {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scroll-behavior: smooth;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}

.ent-content-track::-webkit-scrollbar {
  display: none;
}

.ent-card {
  flex: 0 0 260px;
  scroll-snap-align: start;
  background: #fff;
  border-radius: 18px;
  overflow: hidden;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.06);
}

.ent-card-image {
  width: 100%;
  height: 200px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  font-size: 40px;
  color: #fff;
}

.ent-card-body {
  padding: 16px 20px 20px;
}

.ent-card-title {
  font-size: 15px;
  font-weight: 600;
  letter-spacing: -0.01em;
  margin-bottom: 4px;
}

.ent-card-subtitle {
  font-size: 12px;
  color: #6e6e73;
  margin-bottom: 10px;
}

.ent-card-cta {
  font-size: 13px;
  font-weight: 500;
  color: #0066cc;
}

/* ===== QUICK LINKS ===== */
.quick-links {
  padding: 40px 0 60px;
}

.quick-links-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 22px;
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

.quick-link-btn {
  display: inline-block;
  padding: 10px 20px;
  background: #f5f5f7;
  border-radius: 980px;
  font-size: 14px;
  font-weight: 500;
  color: #1d1d1f;
  letter-spacing: -0.01em;
  transition: background 0.15s;
}

.quick-link-btn:hover {
  background: #e8e8ed;
  text-decoration: none;
}

/* ===== BRAND COLLAB SECTION ===== */
.brand-section {
  padding: 60px 0;
}

/* ===== ACCESSORIES GRID ===== */
.accessory-card {
  flex: 0 0 260px;
}

/* ===== FOOTER ===== */
.footer {
  background: #f5f5f7;
  padding: 60px 0 30px;
  border-top: 1px solid rgba(0, 0, 0, 0.08);
}

.footer-inner {
