}

/* ===== BRAND COLLAB SECTION ===== */
.brand-section {
  padding: 60px 0;
}

/* ===== ACCESSORIES GRID ===== */
.accessory-card {
  flex: 0 0 260px;
}

/* ===== FOOTER ===== */
.footer {
