  padding-bottom: 20px;
  border-bottom: 1px solid rgba(0, 0, 0, 0.08);
  margin-bottom: 30px;
}

.footer-notes p {
  margin-bottom: 8px;
}

.footer-columns {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 30px;
  margin-bottom: 30px;
}

.footer-col-title {
  font-size: 13px;
  font-weight: 600;
  color: #1d1d1f;
  margin-bottom: 12px;
  letter-spacing: -0.01em;
}

.footer-col-links {
  list-style: none;
}

.footer-col-links li {
  margin-bottom: 8px;
}

.footer-col-links a {
  font-size: 13px;
  color: #6e6e73;
  letter-spacing: -0.01em;
  transition: color 0.15s;
}

.footer-col-links a:hover {
  color: #1d1d1f;
  text-decoration: none;
}

.footer-bottom {
  font-size: 12px;
