}

.placeholder-laptop {
  width: 200px;
  height: 130px;
  border-radius: 8px 8px 0 0;
  background: linear-gradient(180deg, #e8e8ed 0%, #d2d2d7 100%);
  border: 2px solid #c7c7cc;
  position: relative;
}

.placeholder-laptop::after {
  content: '';
  position: absolute;
  bottom: -8px;
  left: 15%;
  right: 15%;
  height: 6px;
  background: #c7c7cc;
  border-radius: 0 0 4px 4px;
}

.placeholder-tablet {
  width: 130px;
  height: 180px;
  border-radius: 12px;
  background: linear-gradient(180deg, #e8e8ed 0%, #d2d2d7 100%);
  border: 3px solid #c7c7cc;
}

.placeholder-earbuds {
  width: 60px;
  height: 80px;
  border-radius: 40px 40px 20px 20px;
  background: linear-gradient(180deg, #e8e8ed 0%, #d2d2d7 100%);
  border: 2px solid #c7c7cc;
}

.placeholder-watch {
  width: 60px;
  height: 80px;
  border-radius: 20px;
  background: linear-gradient(180deg, #e8e8ed 0%, #d2d2d7 100%);
  border: 2px solid #c7c7cc;
}

.placeholder-headphones {
  width: 100px;
  height: 100px;
  border-radius: 50%;
  border: 6px solid #c7c7cc;
  position: relative;
}

.placeholder-headphones::before {
  content: '';
  position: absolute;
  top: 50%;
  left: -6px;
  right: -6px;
  height: 30px;
  background: #e8e8ed;
  border-radius: 20px;
  transform: translateY(-50%);
}

.placeholder-speaker {
  width: 100px;
  height: 120px;
  border-radius: 20px;
  background: linear-gradient(180deg, #e8e8ed 0%, #d2d2d7 100%);
  border: 2px solid #c7c7cc;
}

/* ===== RESPONSIVE ===== */
