/* ===== RESET & BASE ===== */
*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: "SF Pro Display", "SF Pro Text", "Helvetica Neue", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  color: #1d1d1f;
  background: #fff;
  line-height: 1.47059;
  font-weight: 400;
  letter-spacing: -0.022em;
}

a {
  color: #0066cc;
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}

img {
  max-width: 100%;
  display: block;
}

button {
  cursor: pointer;
  border: none;
  background: none;
  font-family: inherit;
}

/* ===== NAVIGATION ===== */
.nav {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: rgba(255, 255, 255, 0.8);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid rgba(0, 0, 0, 0.08);
}

.nav-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 22px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 44px;
}

.nav-logo {
  font-size: 21px;
  font-weight: 600;
  color: #1d1d1f;
  letter-spacing: -0.02em;
}

.nav-logo:hover {
  text-decoration: none;
}

.nav-links {
  display: flex;
  gap: 28px;
}

.nav-links a {
  font-size: 13px;
  font-weight: 400;
  color: #1d1d1f;
  letter-spacing: -0.01em;
  transition: color 0.15s;
}

.nav-links a:hover {
  color: #0066cc;
  text-decoration: none;
}

.nav-actions {
  display: flex;
  gap: 18px;
  align-items: center;
}

.nav-actions i {
  font-size: 18px;
  color: #1d1d1f;
  cursor: pointer;
  transition: color 0.15s;
}

.nav-actions i:hover {
  color: #0066cc;
}

.nav-mobile-toggle {
  display: none;
  font-size: 22px;
  color: #1d1d1f;
}

/* ===== RIBBON BANNER ===== */
.ribbon {
  background: #f5f5f7;
  text-align: center;
  padding: 10px 22px;
  font-size: 13px;
  color: #1d1d1f;
  letter-spacing: -0.01em;
}

.ribbon a {
  color: #0066cc;
  font-weight: 400;
}

/* ===== HERO ===== */
.hero {
  text-align: center;
  padding: 80px 22px 60px;
  background: #f5f5f7;
}

.hero-label {
  font-size: 28px;
  font-weight: 600;
  color: #6e6e73;
  letter-spacing: -0.02em;
  margin-bottom: 8px;
}

.hero-title {
  font-size: 56px;
  font-weight: 700;
  letter-spacing: -0.025em;
  line-height: 1.07;
  margin-bottom: 12px;
}

.hero-subtitle {
