.tile-laptop-neo {
  background: linear-gradient(135deg, #e3f2fd 0%, #bbdefb 40%, #90caf9 100%);
}

.tile-tablet-pro {
  background: linear-gradient(135deg, #e8f5e9 0%, #c8e6c9 40%, #a5d6a7 100%);
}

.tile-laptop-pro {
  background: linear-gradient(135deg, #ede7f6 0%, #d1c4e9 40%, #b39ddb 100%);
}

.tile-earbuds {
  background: linear-gradient(135deg, #f3e5f5 0%, #e1bee7 40%, #ce93d8 100%);
}

.tile-trade-in {
  background: linear-gradient(135deg, #fff3e0 0%, #ffe0b2 40%, #ffcc80 100%);
