/* ===== CATEGORY HERO ===== */
.category-hero {
  background: #f5f5f7;
  text-align: center;
  padding: 60px 22px 40px;
}

.category-hero-title {
  font-size: 48px;
  font-weight: 700;
  letter-spacing: -0.025em;
  line-height: 1.1;
  margin-bottom: 10px;
}

.category-hero-subtitle {
  font-size: 19px;
  color: #6e6e73;
  letter-spacing: -0.02em;
}

/* ===== STICKY SECTION NAV ===== */
.section-nav {
  position: sticky;
  top: 44px;
  z-index: 999;
  background: rgba(255, 255, 255, 0.8);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid rgba(0, 0, 0, 0.08);
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.section-nav-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 22px;
  display: flex;
  gap: 0;
}

.section-nav-inner a {
  display: block;
  padding: 14px 18px;
  font-size: 13px;
  font-weight: 500;
  color: #6e6e73;
  white-space: nowrap;
  border-bottom: 2px solid transparent;
  transition: color 0.15s, border-color 0.15s;
  letter-spacing: -0.01em;
}

.section-nav-inner a:hover,
.section-nav-inner a.active {
  color: #1d1d1f;
  border-bottom-color: #1d1d1f;
  text-decoration: none;
}

/* ===== STORE HERO ===== */
.store-hero {
  background: #f5f5f7;
  text-align: center;
  padding: 60px 22px 48px;
}

.store-hero-title {
  font-size: 48px;
  font-weight: 700;
  letter-spacing: -0.025em;
  line-height: 1.1;
  margin-bottom: 10px;
}

.store-hero-subtitle {
  font-size: 21px;
  color: #6e6e73;
  letter-spacing: -0.02em;
  margin-bottom: 24px;
}

/* ===== PRODUCT ICON BAR ===== */
.product-icon-bar {
  background: #fff;
  border-bottom: 1px solid rgba(0, 0, 0, 0.06);
}

.product-icon-bar-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 16px 22px;
  display: flex;
  gap: 12px;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}

.product-icon-bar-inner::-webkit-scrollbar {
  display: none;
}

.product-icon-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  min-width: 80px;
  cursor: pointer;
  padding: 8px 4px;
  transition: opacity 0.15s;
}

.product-icon-item:hover {
  opacity: 0.7;
  text-decoration: none;
}

.product-icon-circle {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
  color: #fff;
  font-weight: 600;
}

.product-icon-label {
  font-size: 11px;
  font-weight: 500;
  color: #1d1d1f;
  letter-spacing: -0.01em;
  text-align: center;
}

/* ===== CAROUSEL ===== */
.carousel-section {
  padding: 60px 0;
}

.carousel-section-light {
  background: #f5f5f7;
}

.carousel-section-dark {
  background: #1d1d1f;
}

.carousel-header {
  max-width: 1200px;
  margin: 0 auto 30px;
  padding: 0 22px;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
}

.carousel-header-info {
  flex: 1;
}

.carousel-header-info .section-label {
  margin-bottom: 6px;
}

.carousel-header-info .section-heading {
  font-size: 32px;
  margin-bottom: 6px;
}

.carousel-header-info .section-subheading {
  font-size: 17px;
  margin-bottom: 0;
}

.carousel-arrows {
  display: flex;
  gap: 8px;
  flex-shrink: 0;
}

.carousel-arrow {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: rgba(0, 0, 0, 0.05);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  color: #1d1d1f;
  transition: background 0.2s, opacity 0.2s;
}

.carousel-arrow:hover {
  background: rgba(0, 0, 0, 0.1);
}

.carousel-arrow:disabled {
  opacity: 0.3;
  cursor: default;
}

.carousel-arrow.light {
  background: rgba(255, 255, 255, 0.15);
  color: #fff;
}

.carousel-arrow.light:hover {
  background: rgba(255, 255, 255, 0.25);
}

.carousel-track {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 22px;
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scroll-behavior: smooth;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}

.carousel-track::-webkit-scrollbar {
  display: none;
}

/* ===== CAROUSEL CARDS ===== */
.carousel-card {
  flex: 0 0 320px;
  scroll-snap-align: start;
  background: #fff;
  border-radius: 18px;
  overflow: hidden;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.06);
  transition: transform 0.2s, box-shadow 0.2s;
}

.carousel-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 28px rgba(0, 0, 0, 0.1);
}

.carousel-card-image {
  width: 100%;
  height: 220px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #fafafa;
}

.carousel-card-body {
  padding: 20px 24px 24px;
}

.carousel-card-badge {
  display: inline-block;
  font-size: 11px;
  font-weight: 600;
  color: #bf4800;
  letter-spacing: 0.02em;
  margin-bottom: 6px;
}

.carousel-card-name {
  font-size: 18px;
  font-weight: 600;
  letter-spacing: -0.02em;
  margin-bottom: 4px;
}

.carousel-card-tagline {
  font-size: 14px;
  color: #6e6e73;
  letter-spacing: -0.01em;
  margin-bottom: 14px;
}

.carousel-card-price {
  font-size: 15px;
  font-weight: 500;
  letter-spacing: -0.01em;
  color: #1d1d1f;
  margin-bottom: 4px;
}

.carousel-card-monthly {
  font-size: 13px;
  color: #6e6e73;
  letter-spacing: -0.01em;
}

.carousel-card-note {
  font-size: 12px;
  color: #6e6e73;
  letter-spacing: -0.01em;
}

/* Dark variant cards */
.carousel-card.dark {
  background: #2d2d2f;
  color: #f5f5f7;
}

.carousel-card.dark .carousel-card-name,
.carousel-card.dark .carousel-card-price {
  color: #f5f5f7;
}

.carousel-card.dark .carousel-card-tagline,
.carousel-card.dark .carousel-card-monthly,
.carousel-card.dark .carousel-card-note {
  color: #a1a1a6;
}

/* Help & support cards */
.help-card {
