}

.help-card-title {
  font-size: 17px;
  font-weight: 600;
  letter-spacing: -0.02em;
  margin-bottom: 8px;
}

.help-card-desc {
  font-size: 14px;
  color: #6e6e73;
  letter-spacing: -0.01em;
}

/* Store difference cards */
.diff-card {
  flex: 0 0 240px;
  scroll-snap-align: start;
  text-align: center;
}

.diff-card-icon {
