  color: #fff;
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-height: 280px;
}

.brand-collab-card .collab-badge {
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: #f5a623;
  margin-bottom: 8px;
}

.brand-collab-card .collab-title {
  font-size: 28px;
  font-weight: 700;
  letter-spacing: -0.025em;
  line-height: 1.1;
  margin-bottom: 10px;
}

.brand-collab-card .collab-desc {
  font-size: 16px;
  color: #a1a1a6;
  letter-spacing: -0.02em;
  margin-bottom: 20px;
}

/* ===== ENTERTAINMENT TABS ===== */
