}

.ent-content {
  display: none;
}

.ent-content.active {
  display: block;
}

.ent-content-track {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scroll-behavior: smooth;
  -webkit-overflow-scrolling: touch;
