  color: #fff;
}

.ent-card-body {
  padding: 16px 20px 20px;
}

.ent-card-title {
  font-size: 15px;
  font-weight: 600;
  letter-spacing: -0.01em;
  margin-bottom: 4px;
}

.ent-card-subtitle {
  font-size: 12px;
  color: #6e6e73;
  margin-bottom: 10px;
}

.ent-card-cta {
  font-size: 13px;
