}

/* ===== QUICK LINKS ===== */
.quick-links {
  padding: 40px 0 60px;
}

.quick-links-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 22px;
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

.quick-link-btn {
  display: inline-block;
  padding: 10px 20px;
  background: #f5f5f7;
  border-radius: 980px;
  font-size: 14px;
  font-weight: 500;
  color: #1d1d1f;
  letter-spacing: -0.01em;
  transition: background 0.15s;
}

.quick-link-btn:hover {
  background: #e8e8ed;
  text-decoration: none;
}

/* ===== BRAND COLLAB SECTION ===== */
.brand-section {
  padding: 60px 0;
}

/* ===== ACCESSORIES GRID ===== */
.accessory-card {
  flex: 0 0 260px;
}

/* ===== FOOTER ===== */
.footer {
  background: #f5f5f7;
  padding: 60px 0 30px;
  border-top: 1px solid rgba(0, 0, 0, 0.08);
}

.footer-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 22px;
}

.footer-notes {
  font-size: 12px;
  color: #6e6e73;
  letter-spacing: -0.01em;
  line-height: 1.5;
  padding-bottom: 20px;
  border-bottom: 1px solid rgba(0, 0, 0, 0.08);
  margin-bottom: 30px;
}

.footer-notes p {
  margin-bottom: 8px;
}

.footer-columns {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 30px;
  margin-bottom: 30px;
}

.footer-col-title {
  font-size: 13px;
  font-weight: 600;
  color: #1d1d1f;
  margin-bottom: 12px;
  letter-spacing: -0.01em;
}

.footer-col-links {
  list-style: none;
}

.footer-col-links li {
  margin-bottom: 8px;
}

.footer-col-links a {
  font-size: 13px;
  color: #6e6e73;
  letter-spacing: -0.01em;
  transition: color 0.15s;
}

.footer-col-links a:hover {
  color: #1d1d1f;
  text-decoration: none;
}

.footer-bottom {
  font-size: 12px;
  color: #6e6e73;
  letter-spacing: -0.01em;
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
}

.footer-bottom-links {
  display: flex;
  gap: 16px;
}

.footer-bottom-links a {
  font-size: 12px;
  color: #6e6e73;
}

/* ===== PLACEHOLDER IMAGES ===== */
.placeholder {
  width: 100%;
  height: 100%;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.placeholder-phone {
  width: 80px;
  height: 150px;
  border-radius: 12px;
  background: linear-gradient(180deg, #e8e8ed 0%, #d2d2d7 100%);
  border: 3px solid #c7c7cc;
}

.placeholder-laptop {
  width: 200px;
  height: 130px;
  border-radius: 8px 8px 0 0;
  background: linear-gradient(180deg, #e8e8ed 0%, #d2d2d7 100%);
  border: 2px solid #c7c7cc;
  position: relative;
}

.placeholder-laptop::after {
  content: '';
  position: absolute;
  bottom: -8px;
  left: 15%;
  right: 15%;
  height: 6px;
  background: #c7c7cc;
  border-radius: 0 0 4px 4px;
}

.placeholder-tablet {
  width: 130px;
  height: 180px;
  border-radius: 12px;
  background: linear-gradient(180deg, #e8e8ed 0%, #d2d2d7 100%);
  border: 3px solid #c7c7cc;
}

.placeholder-earbuds {
  width: 60px;
  height: 80px;
  border-radius: 40px 40px 20px 20px;
  background: linear-gradient(180deg, #e8e8ed 0%, #d2d2d7 100%);
  border: 2px solid #c7c7cc;
}

.placeholder-watch {
  width: 60px;
  height: 80px;
  border-radius: 20px;
  background: linear-gradient(180deg, #e8e8ed 0%, #d2d2d7 100%);
  border: 2px solid #c7c7cc;
}

.placeholder-headphones {
  width: 100px;
  height: 100px;
  border-radius: 50%;
  border: 6px solid #c7c7cc;
  position: relative;
}

.placeholder-headphones::before {
  content: '';
  position: absolute;
  top: 50%;
  left: -6px;
  right: -6px;
  height: 30px;
  background: #e8e8ed;
  border-radius: 20px;
  transform: translateY(-50%);
}

.placeholder-speaker {
  width: 100px;
  height: 120px;
  border-radius: 20px;
  background: linear-gradient(180deg, #e8e8ed 0%, #d2d2d7 100%);
  border: 2px solid #c7c7cc;
}

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .hero-title {
    font-size: 40px;
  }

  .section-heading {
    font-size: 32px;
  }

  .product-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .footer-columns {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 768px) {
  .nav-links {
    display: none;
  }

  .nav-mobile-toggle {
    display: block;
  }

  .hero-title {
    font-size: 32px;
  }

  .section-heading {
    font-size: 28px;
  }

  .product-grid {
    grid-template-columns: 1fr;
  }

  .product-tile {
    min-height: 400px;
    padding: 40px 20px 30px;
  }

  .product-tile-headline {
    font-size: 26px;
  }

  .carousel-card {
    flex: 0 0 260px;
  }

  .help-card {
    flex: 0 0 240px;
  }

  .diff-card {
    flex: 0 0 200px;
  }

  .footer-columns {
    grid-template-columns: 1fr;
  }

  .footer-col-links {
    display: none;
  }

  .footer-col-links.open {
    display: block;
  }

  .footer-col-title {
    cursor: pointer;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 10px 0;
    border-bottom: 1px solid rgba(0, 0, 0, 0.08);
  }

  .footer-col-title::after {
    content: '+';
    font-size: 18px;
    font-weight: 400;
    color: #6e6e73;
  }

  .footer-col-title.open::after {
    content: '−';
  }

  .section-nav-inner a {
    padding: 12px 14px;
    font-size: 12px;
  }

  .carousel-header {
    flex-direction: column;
    align-items: flex-start;
    gap: 16px;
  }
}

@media (max-width: 480px) {
  .hero-title {
    font-size: 28px;
  }

  .section-heading {
    font-size: 24px;
  }

  .hero-actions {
    flex-direction: column;
    align-items: center;
  }

  .carousel-card {
    flex: 0 0 240px;
  }

  .carousel-card-image {
    height: 180px;
  }
}

/* ===== MOBILE NAV MENU ===== */
.nav-mobile-menu {
  display: none;
  position: fixed;
  top: 44px;
  left: 0;
  right: 0;
  bottom: 0;
  background: #fff;
  z-index: 999;
  padding: 30px 22px;
  overflow-y: auto;
}

.nav-mobile-menu.open {
  display: block;
}

.nav-mobile-menu a {
  display: block;
  font-size: 20px;
  font-weight: 500;
  color: #1d1d1f;
  padding: 14px 0;
  border-bottom: 1px solid rgba(0, 0, 0, 0.06);
  letter-spacing: -0.02em;
}

.nav-mobile-menu a:hover {
  color: #0066cc;
  text-decoration: none;
}

/* ===== UTILITY ===== */
.text-center {
  text-align: center;
}

.mt-20 {
  margin-top: 20px;
}

.mb-20 {
  margin-bottom: 20px;
}

/* ===== STORE HERO CATEGORY LINK ===== */
.category-hero-link {
  font-size: 15px;
  color: #0066cc;
  font-weight: 500;
  letter-spacing: -0.01em;
}

/* ===== RESET & BASE ===== */
*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: "SF Pro Display", "SF Pro Text", "Helvetica Neue", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  color: #1d1d1f;
  background: #fff;
  line-height: 1.47059;
  font-weight: 400;
  letter-spacing: -0.022em;
}

a {
  color: #0066cc;
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}

img {
  max-width: 100%;
  display: block;
}

button {
  cursor: pointer;
  border: none;
  background: none;
  font-family: inherit;
}

/* ===== NAVIGATION ===== */
.nav {
  position: sticky;
  top: 0;
