/* ===== CAROUSEL ===== */
.carousel-section {
  padding: 60px 0;
}

.carousel-section-light {
  background: #f5f5f7;
}

.carousel-section-dark {
  background: #1d1d1f;
}

.carousel-header {
  max-width: 1200px;
  margin: 0 auto 30px;
  padding: 0 22px;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
}

.carousel-header-info {
  flex: 1;
}

.carousel-header-info .section-label {
  margin-bottom: 6px;
}

.carousel-header-info .section-heading {
  font-size: 32px;
