  font-size: 17px;
  margin-bottom: 0;
}

.carousel-arrows {
  display: flex;
  gap: 8px;
  flex-shrink: 0;
}

.carousel-arrow {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: rgba(0, 0, 0, 0.05);
