  display: flex;
  align-items: center;
  justify-content: center;
}

.placeholder-phone {
  width: 80px;
  height: 150px;
  border-radius: 12px;
  background: linear-gradient(180deg, #e8e8ed 0%, #d2d2d7 100%);
  border: 3px solid #c7c7cc;
}

.placeholder-laptop {
  width: 200px;
  height: 130px;
  border-radius: 8px 8px 0 0;
  background: linear-gradient(180deg, #e8e8ed 0%, #d2d2d7 100%);
  border: 2px solid #c7c7cc;
  position: relative;
}

.placeholder-laptop::after {
  content: '';
  position: absolute;
  bottom: -8px;
  left: 15%;
  right: 15%;
  height: 6px;
  background: #c7c7cc;
  border-radius: 0 0 4px 4px;
}

.placeholder-tablet {
  width: 130px;
  height: 180px;
  border-radius: 12px;
