}

.placeholder-earbuds {
  width: 60px;
  height: 80px;
  border-radius: 40px 40px 20px 20px;
  background: linear-gradient(180deg, #e8e8ed 0%, #d2d2d7 100%);
  border: 2px solid #c7c7cc;
}

.placeholder-watch {
  width: 60px;
  height: 80px;
  border-radius: 20px;
  background: linear-gradient(180deg, #e8e8ed 0%, #d2d2d7 100%);
  border: 2px solid #c7c7cc;
}

.placeholder-headphones {
  width: 100px;
  height: 100px;
  border-radius: 50%;
  border: 6px solid #c7c7cc;
  position: relative;
}

.placeholder-headphones::before {
  content: '';
  position: absolute;
  top: 50%;
  left: -6px;
  right: -6px;
  height: 30px;
  background: #e8e8ed;
  border-radius: 20px;
  transform: translateY(-50%);
}

.placeholder-speaker {
  width: 100px;
  height: 120px;
  border-radius: 20px;
  background: linear-gradient(180deg, #e8e8ed 0%, #d2d2d7 100%);
  border: 2px solid #c7c7cc;
}

